{"path":"src/java_module.java","content":"// Метод ищет активного пользователя по логину.
// Возвращает Optional<User>, чтобы явно показать, что пользователь может отсутствовать,
// а не возвращать null (это защищает вызывающий код от NullPointerException).
public Optional<User> findActive(String login) {
    // Берём поток из коллекции всех пользователей.
    return users.stream()
        // Первый фильтр: совпадение логина без учёта регистра.
        // Используем equalsIgnoreCase, потому что логин введённый пользователем
        // может отличаться регистром от сохранённого (например, "Admin" vs "admin").
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // Второй фильтр: пользователь должен быть активным.
        // Активность определяется двумя условиями:
        //   1) пользователь не заблокирован (!u.isBlocked());
        //   2) срок действия учётной записи ещё не истёк
        //      (у.getExpiresAt().isAfter(Instant.now()) — дата истечения позже текущего момента).
        // Оба условия объединены через &&, то есть должны выполняться одновременно.
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // findFirst() возвращает первый подходящий элемент как Optional.
        // Если подходящего элемента нет, будет пустой Optional.
        // Используем именно findFirst(), а не findAny(), так как порядок
        // элементов в users имеет значение (например, первый найденный — основной аккаунт).
        .findFirst();
}
"}

{"path":"src/csharp_module.cs","content":"// Метод реализует повторные попытки выполнения асинхронного действия
// с экспоненциальной задержкой между ними (exponential backoff).
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Перебираем все попытки: от 0 до attempts - 1.
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Выполняем действие и сразу возвращаем его результат.
            // Если всё прошло успешно — цикл завершён.
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        // Перехватываем только ошибки HTTP-запросов.
        // Условие "when" гарантирует, что на последней попытке
        // исключение не будет проглочено, а пробросится наружу.
        {
            // Ждём перед следующей попыткой.
            // Задержка растёт экспоненциально: 200мс * 2^i,
            // т.е. 200мс, 400мс, 800мс и т.д. Это позволяет
            // дать серверу время восстановиться после сбоя.
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }

    // Сюда мы попадаем только если все попытки исчерпаны
    // и ни одна из них не завершилась успехом.
    // На практике это недостижимо (на последней попытке
    // исключение пробрасывается), но компилятор требует
    // гарантированный возврат значения, поэтому бросаем
    // InvalidOperationException.
    throw new InvalidOperationException("unreachable");
}
"}

{"path":"src/go_module.go","content":"// worker — функция-воркер, которая обрабатывает входящие задачи (jobs)
// и отправляет результаты в канал results.
//
// Почему именно так:
//   - Функция принимает канал задач (jobs), канал результатов (results)
//     и указатель на WaitGroup (wg). Это позволяет запускать несколько
//     воркеров параллельно, каждый из которых читает из общего канала jobs
//     и пишет в общий канал results. Go сам распределяет задачи между
//     воркерами, потому что чтение из канала блокирует горутины, пока
//     задача не появится.
//   - defer wg.Done() гарантирует, что счётчик WaitGroup будет уменьшен
//     независимо от того, как завершится функция (нормально или с паникой).
//     Это нужно для корректного ожидания завершения всех воркеров через wg.Wait().
//   - Цикл for j := range jobs работает до тех пор, пока канал jobs не будет
//     закрыт. Когда канал закрывается, range возвращает false и цикл завершается.
//     Это стандартный паттерн "producer-consumer" в Go.
//   - Если при обработке задачи возникает ошибка, мы логируем её и переходим
//     к следующей задаче (continue). Это делает воркер устойчивым к отдельным
//     ошибкам — одна неудачная задача не останавливает всю обработку.
//     Альтернатива — отправить ошибку в отдельный канал, но это усложняет
//     архитектуру без явной необходимости.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // Уменьшаем счётчик WaitGroup при выходе из функции.
    // Используем defer, чтобы гарантировать вызов даже при панике.
    defer wg.Done()

    // Обрабатываем задачи, пока канал jobs не будет закрыт.
    for j := range jobs {
        // Вызываем функцию обработки конкретной задачи.
        r, err := process(j)

        // Если произошла ошибка — логируем её и пропускаем задачу.
        // Задача не будет отправлена в results, т.к. результат невалиден.
        if err != nil {
            log.Printf("job %d: %v", j.ID, err)
            continue
        }

        // Отправляем успешный результат в канал результатов.
        // Оператор <- блокирует горутина, пока потребитель не заберёт значение,
        // что обеспечивает backpressure: если потребители медленные,
        // воркеры тоже замедлятся, а не будут накапливать результаты в памяти.
        results <- r
    }
}
"}

{"path":"src/typescript_module.ts","content":"/**
 * Функция debounce (дебаунс) — классический паттерн для «гашения» частых вызовов.
 *
 * Что делает:
 *   Возвращает обёртку над переданной функцией `fn`, которая откладывает её
 *   выполнение на `ms` миллисекунд. Если за это время функция вызывается снова,
 *   предыдущий таймер сбрасывается и отсчёт начинается заново. В итоге `fn`
 *   выполнится ровно один раз — через `ms` мс после последнего вызова обёртки.
 *
 * Зачем так:
 *   - Тип `T extends (...a: any[]) => void` гарантирует, что мы принимаем только
 *     функцию, а не произвольное значение. Это защищает от ошибок вроде
 *     `debounce(42, 100)` уже на этапе компиляции.
 *   - `Parameters<T>` извлекает сигнатуру аргументов исходной функции, поэтому
 *     возвращаемая обёртка принимает те же аргументы, что и `fn`. Благодаря этому
 *     TypeScript корректно проверяет типы при каждом вызове и подсказывает их в IDE.
 *   - `ReturnType<typeof setTimeout>` используется вместо `number`, потому что
 *     тип возвращаемого значения `setTimeout` зависит от среды: в Node.js это
 *     объект `NodeJS.Timeout`, а в браузере — `number`. Такой подход делает код
 *     переносимым между окружениями без потери типобезопасности.
 *   - Переменная `t` хранит идентификатор текущего таймера. Она объявлена снаружи
 *     возвращаемой функции (в замыкании), чтобы состояние сохранялось между
 *     вызовами обёртки. Изначально она `undefined` — таймера ещё нет.
 *   - При каждом вызове обёртки мы сначала отменяем предыдущий таймер
 *     (`clearTimeout`), если он был создан, и лишь затем ставим новый. Именно это
 *     и создаёт эффект «отложенного выполнения после паузы».
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Идентификатор таймера; живёт в замыкании и переживает все вызовы обёртки.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем функцию-обёртку с той же сигнатурой параметров, что и `fn`.
  return (...args: Parameters<T>) => {
    // Если таймер уже стоит — отменяем его, чтобы сбросить отсчёт времени.
    if (t) clearTimeout(t);

    // Ставим новый таймер: через `ms` мс вызываем оригинальную функцию
    // с теми аргументами, которые были переданы в последний раз.
    t = setTimeout(() => fn(...args), ms);
  };
}
"}

{"path":"src/kotlin_module.kt","content":"/**
 * Безопасная (thread-safe) версия функции [MutableMap.getOrPut].
 *
 * @param K тип ключей в карте.
 * @param V тип значений в карте.
 * @param key ключ, по которому ищем значение.
 * @param factory фабрика, которая создаёт новое значение, если его ещё нет в карте.
 * @return значение, связанное с [key]: либо уже существующее, либо только что созданное фабрикой.
 */
fun <K, V> MutableMap<K, V>.getOrGetSafe(key: K, factory: () -> V): V =
    // Оборачиваем всю операцию чтения/записи в synchronized(this), чтобы гарантировать
    // атомарность: между проверкой наличия ключа и записью нового значения не может
    // вмешаться другой поток. Без этого два потока могли бы одновременно увидеть,
    // что ключа нет, и оба бы создали и записали значение — это гонка данных (race condition).
    synchronized(this) {
        // this[key] ?: ... — если значение для ключа уже есть, возвращаем его.
        // Если значения нет (null), вызываем фабрику, сохраняем результат в карту
        // (через .also { this[key] = it }) и возвращаем его.
        this[key] ?: factory().also { this[key] = it }
    }
"}

{"path":"src/rust_module.rs","content":"use std::collections::HashMap;

/// Разбирает строку в формате "ключ1=значение1;ключ2=значение2" в хеш-мапу.
///
/// Формат входной строки: пары «ключ=значение», разделённые точкой с запятой.
/// Пример: `"Name=John;Age=30"` -> `{"name": "John", "age": "30"}`.
///
/// Почему именно так:
/// - Используем итераторы (`split`, `filter_map`, `map`, `collect`), потому что
///   это идиоматичный, производительный и лаконичный способ обработки строк в Rust:
///   нет промежуточных коллекций, всё делается за один проход по данным.
/// - Ключ приводим к нижнему регистру (`to_lowercase`) — чтобы поиск не зависел
///   от регистра ключа (например, "Name" и "name" считались бы одинаковыми).
/// - Значение оставляем как есть, но обрезаем пробелы по краям (`trim`).
/// - Пары без символа `=` просто отбрасываем (`filter_map` возвращает `None`
///   для таких элементов), а не вызываем панику — это делает функцию устойчивой
///   к некорректному вводу.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';') // 1. Режем строку на части по разделителю ';'
        .filter_map(|p| p.split_once('=')) // 2. Оставляем только те части, где есть '=',
                                           //    и разбиваем их на пару (ключ, значение).
                                           //    split_once берёт первый '=' — если ключ
                                           //    содержит '=', он останется целиком в ключе.
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string())) // 3. Приводим ключ
                                           //    к нижнему регистру и обрезаем пробелы,
                                           //    значение тоже очищаем от лишних пробелов.
        .collect() // 4. Собираем все пары в HashMap<String, String>.
}
"}
